function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Alice', 'Bob', 'Tom', 'Jerry', 'John', 'Mira'];
  const goods = ['keyboard', 'mouse', 'screen', 'hard disk', 'cable', 'webcam'];
  const customerCount = small ? Math.floor(rand() * 5) : 200;
  const productCount = small ? 1 + Math.floor(rand() * 4) : 25;
  const Customers = [], Products = [], Orders = [];
  for (let id = 1; id <= customerCount; id++) Customers.push([id, pick(names)]);
  for (let id = 1; id <= productCount; id++) Products.push([id, pick(goods), 10 * (1 + Math.floor(rand() * 60))]);
  // Few products per customer in small sets, so counts tie often.
  const days = Array.from({ length: small ? 5 : 120 }, (_, i) => new Date(Date.UTC(2020, 5, 1 + i)).toISOString().slice(0, 10));
  const target = customerCount ? (small ? Math.floor(rand() * 9) : 2000) : 0;
  const used = new Set();
  for (let attempt = 0; Orders.length < target && attempt < target * 5; attempt++) {
    const customer = 1 + Math.floor(rand() * customerCount);
    // Large sets lean toward low product ids so favourites exist but ties still happen.
    const product = 1 + Math.floor((small ? rand() : rand() * rand()) * productCount);
    const date = pick(days);
    const key = `${customer}/${product}/${date}`;
    if (used.has(key)) continue;
    used.add(key);
    Orders.push([Orders.length + 1, date, customer, product]);
  }
  return [{ Customers, Orders, Products }];
}
